def create_doc(doctype: str):
	data = get_request_form_data()
	data.pop("doctype", None)
	return frappe.new_doc(doctype, **data).insert()

def read_doc(doctype: str, name: str):
	# Backward compatiblity
	if "run_method" in frappe.form_dict:
		return execute_doc_method(doctype, name)

	doc = frappe.get_doc(doctype, name)
	doc.check_permission("read")
	doc.apply_fieldlevel_read_permissions()
	if sbool(frappe.form_dict.get("expand_links")):
		doc_dict = doc.as_dict()
		get_values_for_link_and_dynamic_link_fields(doc_dict)
		get_values_for_table_and_multiselect_fields(doc_dict)
		return doc_dict

	return doc

def get(
	doctype: str,
	name: str | int | None = None,
	filters: str | list | dict[str, Any] | None = None,
	parent: str | None = None,
):
	"""Return a document by name or filters.

	:param doctype: DocType of the document to be returned
	:param name: return document of this `name`
	:param filters: If name is not set, filter by these values and return the first match"""

	if name:
		doc = frappe.get_doc(doctype, name)
	elif filters or filters == {}:
		doc = frappe.get_doc(doctype, frappe.parse_json(filters))
	else:
		doc = frappe.get_doc(doctype)  # single

	doc.check_permission()
	doc.apply_fieldlevel_read_permissions()

	return doc.as_dict()

def insert(doc: str | dict[str, Any] | None = None):
	"""Insert a document

	:param doc: JSON or dict object to be inserted"""
	if isinstance(doc, str):
		doc = json.loads(doc)

	return insert_doc(doc).as_dict()

def save(doc: str | dict[str, Any]):
	"""Update (save) an existing document

	:param doc: JSON or dict object with the properties of the document to be updated"""
	if isinstance(doc, str):
		doc = json.loads(doc)

	doc = frappe.get_doc(doc)
	doc.save()

	return doc.as_dict()

def check_permission(self, permtype="read", permlevel=None):
	"""Raise `frappe.PermissionError` if not permitted"""
	if not self.has_permission(permtype):
		self._handle_permission_failure(permtype)

def db_insert(self, ignore_if_duplicate=False):
	"""INSERT the document (with valid columns) in the database.

	args:
	        ignore_if_duplicate: ignore primary key collision
	                                        at database level (postgres)
	                                        in python (mariadb)
	"""
	if not self.name:
		# name will be set by document class in most cases
		set_new_name(self)

	conflict_handler = ""
	returning = ""
	# On postgres we can't implcitly ignore PK collision
	# So instruct pg to ignore `name` field conflicts
	if (
		(ignore_if_duplicate or self.meta.autoname == "hash")
		and frappe.db.db_type == "postgres"
		and (self.flags.retry_count or 0) < 5
	):
		conflict_handler = "on conflict (name) do nothing"
		if self.meta.autoname == "hash":
			returning = "RETURNING name"

	if not self.creation:
		self.creation = self.modified = now()
		self.owner = self.modified_by = frappe.session.user

	# if doctype is "DocType", don't insert null values as we don't know who is valid yet
	d = self.get_valid_dict(
		convert_dates_to_str=True,
		ignore_nulls=self.doctype in DOCTYPES_FOR_DOCTYPE,
		ignore_virtual=True,
	)

	columns = list(d)
	try:
		name = frappe.db.sql(
			"""INSERT INTO `tab{doctype}` ({columns})
				VALUES ({values}) {conflict_handler} {returning}""".format(
				doctype=self.doctype,
				columns=", ".join("`" + c + "`" for c in columns),
				values=", ".join(["%s"] * len(columns)),
				conflict_handler=conflict_handler,
				returning=returning,
			),
			list(d.values()),
		)
		if (
			frappe.db.db_type == "postgres" and self.meta.autoname == "hash" and not name
		):  # To avoid a transaction block, we regen in try (pg specific)
			return self._handle_hash_conflict()
	except Exception as e:
		if frappe.db.is_primary_key_violation(e):
			if self.meta.autoname == "hash":
				# hash collision? try again
				return self._handle_hash_conflict()

			if not ignore_if_duplicate:
				frappe.msgprint(
					_("{0} {1} already exists").format(_(self.doctype), frappe.bold(self.name)),
					title=_("Duplicate Name"),
					indicator="red",
				)
				raise frappe.DuplicateEntryError(self.doctype, self.name, e)

		elif frappe.db.is_unique_key_violation(e):
			# unique constraint
			self.show_unique_validation_message(e)

		else:
			raise

	self.set("__islocal", False)
